	/** 
	 * jumpstart the process by instantiating2 Person
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		personId = PersonService.getPersonInstance()
		.createPerson( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		PersonService.getPersonInstance()
				.createPerson( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.personSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Person : " + successValue.getPersonId());
							  if (successValue.getPersonId().equals(personId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfPersonList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Person test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on person consumed")
					);
			subscriber.personSubscribe( personId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Person : " + successValue.getPersonId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfPersonList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on person for personId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Person. 
	 */
	protected Person read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Person" );

		Person entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Person with primary key" );
		msg.append( personId );
		
		PersonFetchOneSummary fetchOneSummary = new PersonFetchOneSummary( personId );

		try {
			entity = PersonService.getPersonInstance().getPerson( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Person " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Person.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Person." );

		StringBuilder msg = new StringBuilder( "Failed to update a Person : " );        
		Person entity = read();
		UpdatePersonCommand command = generateUpdateCommand();
		command.setPersonId(entity.getPersonId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Person." );

			// for use later on...
			personId = entity.getPersonId();

			PersonService proxy = PersonService.getPersonInstance();  

			proxy.updatePerson( command ).get();

			LOGGER.info( "-- Successfully saved Person - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + personId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Person.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Person." );

		Person entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Person with id " + personId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Person with id " + personId );

			throw e;
		}

		try{
			PersonService.getPersonInstance().delete( new DeletePersonCommand( entity.getPersonId() ) ).get();
			LOGGER.info( "-- Successfully deleted Person with id " + personId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Person with id " + personId );

			throw e;
		}
	}

	/**
	 * get all Persons.
	 */
	protected List<Person> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Persons:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Person : " );        
		List<Person> collection  = new ArrayList<>();

		try {
			// call the static get method on the PersonService
			collection = PersonService.getPersonInstance().getAllPerson();
			assertNotNull( collection, "An Empty collection of Person was incorrectly returned.");
			
			// Now print out the values
			Person entity = null;            
			Iterator<Person> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getPersonId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

